(7608291, 1230534, 67145, '<td valign="top">LOVE LOVE LOVE .!!!. this is wonderful .. it really makes me smile .. 10 points for totally satisfying the challenge  .. and for making it about dogs .. dogs are the best .. :)</td>', 'LOVE LOVE LOVE .!!!. this is wonderful .. it really makes me smile .. 10 points for totally satisfying the challenge  .. and for making it about dogs .. dogs are the best .. :)', '2019-01-13 16:19:33.000000', NULL, 1),
(7608293, 1230526, 67145, '<td valign="top">this is one of my very favourites in the challenge .. is has such a wonderful joyful feel to it and made me smile .. everything about this works .. your crop .. your tilt and catching the connection between the child and the adult .. the waves are an added bonus .. and of course the black and white . . perfecto .. !! .. :)</td>', 'this is one of my very favourites in the challenge .. is has such a wonderful joyful feel to it and made me smile .. everything about this works .. your crop .. your tilt and catching the connection between the child and the adult .. the waves are an added bonus .. and of course the black and white . . perfecto .. !! .. :)', '2019-01-13 16:23:24.000000', NULL, 1),
