(7608387, 1230339, 141319, '<td valign="top">This is a fab shot! Thanks - for the dedication :-) - not a cowgirl really, but at home in the saddle anyway.</td>', 'This is a fab shot! Thanks - for the dedication :-) - not a cowgirl really, but at home in the saddle anyway.', '2019-01-14 05:34:56.000000', NULL, 0),
